tb_script:
#!/bin/bash
set -u

cd /home/ibex || exit 1

TEST_NAME="debug_cause_haltreq"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_LOG="${TB_DIR}/build.log"
SIM_LOG="${TB_DIR}/sim.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include <cstdint>
#include <cstdio>
#include <cstdlib>

#include "Vibex_controller.h"
#include "verilated.h"

static vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

static void eval_and_advance(Vibex_controller &top, uint8_t clk_level) {
  top.clk_i = clk_level;
  top.eval();
  main_time += 5;
}

static void init_inputs(Vibex_controller &top) {
  top.rst_ni = 0;
  top.illegal_insn_i = 0;
  top.ecall_insn_i = 0;
  top.mret_insn_i = 0;
  top.dret_insn_i = 0;
  top.wfi_insn_i = 0;
  top.ebrk_insn_i = 0;
  top.csr_pipe_flush_i = 0;
  top.instr_valid_i = 0;
  top.instr_i = 0;
  top.instr_compressed_i = 0;
  top.instr_is_compressed_i = 0;
  top.instr_bp_taken_i = 0;
  top.instr_fetch_err_i = 0;
  top.instr_fetch_err_plus2_i = 0;
  top.pc_id_i = 0;
  top.lsu_addr_last_i = 0;
  top.load_err_i = 0;
  top.load_intg_err_i = 0;
  top.store_err_i = 0;
  top.branch_set_i = 0;
  top.branch_not_set_i = 0;
  top.jump_set_i = 0;
  top.csr_mstatus_mie_i = 0;
  top.irq_pending_i = 0;
  top.irqs_i = 0;
  top.irq_nm_ext_i = 0;
  top.debug_req_i = 0;
  top.debug_single_step_i = 0;
  top.debug_ebreakm_i = 0;
  top.debug_ebreaku_i = 0;
  top.trigger_match_i = 0;
  top.priv_mode_i = 3;
  top.stall_id_i = 0;
  top.stall_wb_i = 0;
  top.ready_wb_i = 1;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  Vibex_controller top;
  init_inputs(top);

  eval_and_advance(top, 0);
  for (int i = 0; i < 2; ++i) {
    eval_and_advance(top, 1);
    eval_and_advance(top, 0);
  }

  top.rst_ni = 1;
  top.eval();

  bool armed_debug_req = false;

  for (int cycle = 0; cycle < 20; ++cycle) {
    eval_and_advance(top, 1);

    if (armed_debug_req) {
      top.debug_req_i = 0;
      top.eval();

      if (!(top.debug_csr_save_o && top.csr_save_cause_o)) {
        std::fprintf(stderr, "ERROR: controller did not enter debug mode as expected\n");
        return 1;
      }

      std::printf("OBSERVED_DEBUG_CAUSE=%u\n", static_cast<unsigned>(top.debug_cause_o));
      if (top.debug_cause_o != 3) {
        std::fprintf(stderr, "ERROR: expected DBG_CAUSE_HALTREQ(3), got %u\n",
                     static_cast<unsigned>(top.debug_cause_o));
        return 1;
      }

      std::printf("SIM PASS: debug cause preserved as HALTREQ\n");
      return 0;
    }

    if (top.controller_run_o) {
      top.debug_req_i = 1;
      top.eval();
      armed_debug_req = true;
    }

    eval_and_advance(top, 0);
  }

  std::fprintf(stderr, "ERROR: controller never reached debug entry check\n");
  return 1;
}
EOF

set +e
verilator -sv --cc --exe --build \
  --top-module ibex_controller \
  --Mdir "${TB_DIR}/obj_dir" \
  -DSYNTHESIS \
  -Irtl \
  -Ivendor/lowrisc_ip/ip/prim/rtl \
  -Ivendor/lowrisc_ip/dv/sv/dv_utils \
  -Wno-fatal \
  rtl/ibex_pkg.sv \
  rtl/ibex_controller.sv \
  "${TB_DIR}/sim_main.cpp" \
  > "${BUILD_LOG}" 2>&1
build_rc=$?

echo "HWE_BENCH_RESULTS_START"

if [ "${build_rc}" -ne 0 ]; then
  cat "${BUILD_LOG}"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

"${TB_DIR}/obj_dir/Vibex_controller" > "${SIM_LOG}" 2>&1
sim_rc=$?
cat "${SIM_LOG}"

if [ "${sim_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

