#!/bin/bash
set +e

cd /home/ibex || exit 1

TEST_NAME="fetch_fifo_unaligned_error_pc"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_DIR="${TB_DIR}/build"

mkdir -p "${TB_DIR}" "${BUILD_DIR}"

echo "HWE_BENCH_RESULTS_START"

cat > "${TB_DIR}/tb.cc" <<'EOF'
#include "Vibex_fetch_fifo.h"
#include "verilated.h"

#include <cstdint>
#include <iostream>

namespace {

void eval_low(Vibex_fetch_fifo &top) {
  top.clk_i = 0;
  top.eval();
}

void tick(Vibex_fetch_fifo &top) {
  top.clk_i = 0;
  top.eval();
  top.clk_i = 1;
  top.eval();
}

bool expect_eq(uint32_t actual, uint32_t expected, const char *message) {
  if (actual == expected) {
    return true;
  }

  std::cerr << "TB_FAIL: " << message
            << " expected=0x" << std::hex << expected
            << " actual=0x" << actual << std::dec << std::endl;
  return false;
}

}  // namespace

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  Vibex_fetch_fifo top;

  top.rst_ni = 0;
  top.clear_i = 0;
  top.in_valid_i = 0;
  top.in_addr_i = 0;
  top.in_rdata_i = 0;
  top.in_err_i = 0;
  top.out_ready_i = 1;

  eval_low(top);
  tick(top);
  tick(top);

  top.rst_ni = 1;
  eval_low(top);

  top.clear_i = 1;
  top.in_addr_i = 2;
  tick(top);

  top.clear_i = 0;
  top.in_valid_i = 1;
  top.in_rdata_i = 0x00030000u;
  top.in_err_i = 1;
  eval_low(top);

  std::cout << "OBSERVE out_valid=" << static_cast<int>(top.out_valid_o)
            << " out_addr=0x" << std::hex << top.out_addr_o
            << " out_addr_next=0x" << top.out_addr_next_o
            << " out_err=0x" << static_cast<int>(top.out_err_o)
            << std::dec << std::endl;

  if (!expect_eq(top.out_addr_o, 2u,
                 "unaligned scenario must keep the instruction address at 0x2")) {
    return 1;
  }

  if (!expect_eq(top.out_valid_o, 0u,
                 "errored unaligned 32-bit instruction must wait for its second half")) {
    return 1;
  }

  if (!expect_eq(top.out_addr_next_o, 6u,
                 "errored unaligned 32-bit instruction must increment the PC by 4")) {
    return 1;
  }

  std::cout << "TB_PASS" << std::endl;
  return 0;
}
EOF

verilator --cc --sv -Wno-fatal \
  -Ivendor/lowrisc_ip/prim/rtl \
  --top-module ibex_fetch_fifo \
  rtl/ibex_fetch_fifo.sv \
  --exe "${TB_DIR}/tb.cc" \
  --build \
  -Mdir "${BUILD_DIR}"
rc=$?

if [ $rc -eq 0 ]; then
  "${BUILD_DIR}/Vibex_fetch_fifo"
  rc=$?
fi

if [ $rc -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi

echo "HWE_BENCH_RESULTS_END"

exit $rc

resolved_issues.body:
I'm currently evaluating PULPissimo platform with Ibex core and I encountered some strange behaviour with interrupts. It seems that after hitting breakpoint `mie` in `mstatus` register is reset to 0.

Here is my setup:

- PULPissimo with Ibex core and [pulp-platform/riscv-dbg](https://github.com/pulp-platform/riscv-dbg) as debug core,
- ZedBoard (Xilinx Zynq, `master` version of all cores) and Terasic DE10-Nano (Altera Cyclone-V, with modifications to make the code compatible with Quartus),
- Digilent HS2 JTAG programmer,
- OpenOCD compiled basing on [instructions from PULPissimo](https://github.com/pulp-platform/pulpissimo/#gdb-and-openocd),
- [pulp-platform/pulp-riscv-gnu-toolchain](https://github.com/pulp-platform/pulp-riscv-gnu-toolchain).

OpenOCD config and log as well as gdb log (including issued commands) can be found [here](https://gist.github.com/MarekPikula/63bd5a35dcffa2361a1a7bc3de5642f9).

Code:
```c
#include <stdint.h>

int main() {
  register int mstatus_mie = (1<<3); // mstatus.mie
  asm volatile ("csrw 0x300, %0" :: "r" (mstatus_mie) );

  uint32_t mstatus[3];
  asm volatile ("csrr %0, 0x300" : "=r" (mstatus[0]));
  asm volatile ("nop");  // First breakpoint

  asm volatile ("csrr %0, 0x300" : "=r" (mstatus[1]));
  asm volatile ("nop");  // Second breakpoint

  asm volatile ("csrw 0x300, %0" :: "r" (mstatus_mie) );
  asm volatile ("csrr %0, 0x300" : "=r" (mstatus[2]));
  asm volatile ("nop");  // Third breakpoint

  return 0;
}
```

What the code does is set `mie` flag in `mstatus` register (0x300) and store it in `mstatus[0]`, then after hitting breakpoint read it to `mstatus[1]` and to confirm, `mstatus` register is written again and result stored in `mstatus[2]`.

Basically after sending `x/3x mstatus` gdb returns: `0x00001808	0x00001800	0x00001808`, so in `mstatus[0]` and `mstatus[2]` `mie` flag is set, whereas in `mstatus[1]` it is not set, although, to my understanding, it should be recovered after going out of debug mode.

Is it expected behaviour? If not what can I do to further test it?

