#include <cstdint>
#include <cstdio>
#include <verilated.h>
#include "Vtb_debug_mode_exception.h"

namespace {

constexpr uint32_t CSR_OP_READ = 0;
constexpr uint32_t CSR_MSTATUS = 0x300;
constexpr uint32_t CSR_MEPC = 0x341;
constexpr uint32_t CSR_MCAUSE = 0x342;
constexpr uint32_t CSR_MTVAL = 0x343;
constexpr uint32_t EXC_CAUSE_ILLEGAL_INSN = 0x2;

void tick(Vtb_debug_mode_exception &top) {
  top.clk_i = 0;
  top.eval();
  top.clk_i = 1;
  top.eval();
}

uint32_t read_csr(Vtb_debug_mode_exception &top, uint32_t addr) {
  top.csr_access_i = 0;
  top.csr_op_i = CSR_OP_READ;
  top.csr_wdata_i = 0;
  top.csr_addr_i = addr;
  top.eval();
  return top.csr_rdata_o;
}

}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  Vtb_debug_mode_exception top;

  for (int i = 0; i < 3; ++i) {
    tick(top);
  }
  top.rst_ni = 1;
  for (int i = 0; i < 2; ++i) {
    tick(top);
  }

  const uint32_t reset_mstatus = read_csr(top, CSR_MSTATUS);
  if (reset_mstatus != 0x00000080u) {
    std::printf("TB_RESULT: FAIL\n");
    std::printf("TB_RESET unexpected_mstatus=0x%08x\n", reset_mstatus);
    top.final();
    return 1;
  }

  top.debug_mode_i = 1;
  top.csr_mcause_i = EXC_CAUSE_ILLEGAL_INSN;
  top.csr_mtval_i = 0xDEADBEEFu;
  top.pc_if_i = 0x10000040u;
  top.csr_save_if_i = 1;
  top.csr_save_cause_i = 1;
  tick(top);

  top.csr_save_if_i = 0;
  top.csr_save_cause_i = 0;
  top.pc_if_i = 0;
  top.csr_mtval_i = 0;
  tick(top);

  const uint32_t mepc = read_csr(top, CSR_MEPC);
  const uint32_t mcause = read_csr(top, CSR_MCAUSE);
  const uint32_t mtval = read_csr(top, CSR_MTVAL);
  const uint32_t mstatus = read_csr(top, CSR_MSTATUS);

  if ((mepc != 0x00000000u) || (mcause != 0x00000000u) ||
      (mtval != 0x00000000u) || (mstatus != 0x00000080u)) {
    std::printf("TB_RESULT: FAIL\n");
    std::printf("TB_STATE mepc=0x%08x mcause=0x%08x mtval=0x%08x mstatus=0x%08x\n",
                mepc, mcause, mtval, mstatus);
    top.final();
    return 1;
  }

  std::printf("TB_RESULT: PASS\n");
  std::printf("TB_STATE mepc=0x%08x mcause=0x%08x mtval=0x%08x mstatus=0x%08x\n",
              mepc, mcause, mtval, mstatus);
  top.final();
  return 0;
}
EOF

emit_test_result() {
