if [ "${sim_rc}" -eq 0 ] && grep -q 'TB_RESULT: PASS' "${SIM_LOG}"; then
  emit_test_result "PASS"
  exit 0
fi

emit_test_result "FAIL"
exit 1

#!/bin/bash
cd /home/ibex
set +e

TEST_NAME="debug_entry_priv_mode"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_DIR="${TB_DIR}/obj_dir"
TOP="tb_debug_priv"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/${TOP}.sv" <<'EOF'
module tb_debug_priv (
  input  logic clk_i,
  input  logic rst_ni,
  output logic test_done_o,
  output logic test_pass_o
);
  localparam logic [31:0] BootAddr        = 32'h00000000;
  localparam logic [31:0] UserEntryAddr   = 32'h000000A0;
  localparam logic [31:0] DmHaltAddr      = 32'h00000100;
  localparam logic [31:0] DmExceptionAddr = 32'h00000180;

  logic        instr_req;
  logic        instr_gnt;
  logic        instr_rvalid;
  logic [31:0] instr_addr;
  logic [31:0] instr_rdata;
  logic        instr_err;

  logic        data_req;
  logic        data_gnt;
  logic        data_rvalid;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_addr;
  logic [31:0] data_wdata;
  logic [31:0] data_rdata;
  logic        data_err;

  logic        debug_req;
  logic        core_sleep;

  logic [31:0] imem [0:127];

  integer idx;
  integer cycle_count;
  logic   saw_u_mode;

  initial begin
    for (idx = 0; idx < 128; idx = idx + 1) begin
      imem[idx] = 32'h00000013;
    end

    // Boot in M-mode, set mepc to UserEntryAddr, clear mstatus.mpp, then execute mret.
    imem[32'h80 >> 2] = 32'h0a000093; // addi x1, x0, 0x0a0
    imem[32'h84 >> 2] = 32'h34109073; // csrw mepc, x1
    imem[32'h88 >> 2] = 32'h30001073; // csrw mstatus, x0
    imem[32'h8c >> 2] = 32'h30200073; // mret

    // Stay in U-mode until the testbench raises debug_req.
    imem[UserEntryAddr >> 2]         = 32'h00000013; // nop
    imem[(UserEntryAddr + 32'd4) >> 2] = 32'h0000006f; // jal x0, 0

    // Remain in debug ROM so the privilege mode can be observed after entry.
    imem[DmHaltAddr >> 2]            = 32'h0000006f; // jal x0, 0
    imem[DmExceptionAddr >> 2]       = 32'h0000006f; // jal x0, 0

    test_done_o = 1'b0;
    test_pass_o = 1'b0;
    debug_req   = 1'b0;
    cycle_count = 0;
    saw_u_mode  = 1'b0;
  end

  assign instr_gnt = instr_req;
  assign data_gnt  = data_req;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      instr_rvalid <= 1'b0;
      instr_rdata  <= 32'h00000013;
      instr_err    <= 1'b0;
      data_rvalid  <= 1'b0;
      data_rdata   <= 32'h00000000;
      data_err     <= 1'b0;
    end else begin
      instr_rvalid <= instr_req;
      instr_err    <= 1'b0;
      if (instr_req && (instr_addr[31:9] == '0)) begin
        instr_rdata <= imem[instr_addr[8:2]];
      end else begin
        instr_rdata <= 32'h00000013;
      end

      data_rvalid <= data_req;
      data_rdata  <= 32'h00000000;
      data_err    <= 1'b0;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      test_done_o <= 1'b0;
      test_pass_o <= 1'b0;
      debug_req   <= 1'b0;
      cycle_count <= 0;
      saw_u_mode  <= 1'b0;
    end else if (!test_done_o) begin
      cycle_count <= cycle_count + 1;

      if (!saw_u_mode && (dut.cs_registers_i.priv_lvl_q == 2'b00)) begin
        saw_u_mode <= 1'b1;
        $display("TRACE: entered_u_mode cycle=%0d pc_id=0x%08x", cycle_count, dut.pc_id);
      end

      debug_req <= saw_u_mode && !dut.debug_mode;

      if (dut.debug_mode) begin
        $display("TRACE: debug_mode cycle=%0d priv_lvl_q=%0d dcsr_prv=%0d pc_if=0x%08x pc_id=0x%08x",
                 cycle_count,
                 dut.cs_registers_i.priv_lvl_q,
                 dut.cs_registers_i.dcsr_q.prv,
                 dut.pc_if,
                 dut.pc_id);
        if (dut.cs_registers_i.priv_lvl_q == 2'b11) begin
          test_pass_o <= 1'b1;
          $display("SIM_RESULT PASS priv_lvl_q=%0d dcsr_prv=%0d",
                   dut.cs_registers_i.priv_lvl_q,
                   dut.cs_registers_i.dcsr_q.prv);
        end else begin
