tb_script:
#!/bin/bash
set -euo pipefail

cd /home/ibex

TEST_NAME="lsu_unaligned_first_error"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
SIM_BIN="${TB_DIR}/obj_dir/Vibex_load_store_unit"
SIM_LOG="${TB_DIR}/sim.log"

finish_test() {
  local status="$1"
  local exit_code="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${exit_code}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include <cstdint>
#include <iostream>
#include "Vibex_load_store_unit.h"
#include "verilated.h"

static vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

static void tick(Vibex_load_store_unit* top) {
  top->clk_i = 1;
  top->eval();
  main_time += 5;
  top->clk_i = 0;
  top->eval();
  main_time += 5;
}

static void check(bool cond, const char* msg, int& error_count) {
  if (!cond) {
    std::cout << "TB_ERROR: " << msg << std::endl;
    ++error_count;
  }
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Vibex_load_store_unit* top = new Vibex_load_store_unit;
  const uint32_t kStartAddr = 0x00001001u;
  const uint32_t kSecondAddr = kStartAddr + 4u;
  int error_count = 0;

  top->clk_i = 0;
  top->rst_ni = 0;
  top->data_gnt_i = 0;
  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  top->data_pmp_err_i = 0;
  top->data_rdata_i = 0;
  top->data_we_ex_i = 1;
  top->data_type_ex_i = 0;
  top->data_wdata_ex_i = 0xAABBCCDDu;
  top->data_sign_ext_ex_i = 0;
  top->data_req_ex_i = 0;
  top->adder_result_ex_i = kStartAddr;
  top->eval();

  tick(top);
  tick(top);
  top->rst_ni = 1;
  top->eval();

  top->data_req_ex_i = 1;
  top->data_gnt_i = 1;
  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  top->eval();
  check(top->data_req_o == 1, "first request was not issued", error_count);
  check(top->data_addr_o == 0x00001000u, "first request address mismatch", error_count);
  check(top->data_be_o == 0xEu, "first request byte enable mismatch", error_count);
  check(top->data_valid_o == 0, "data_valid asserted during first grant", error_count);
  tick(top);

  top->data_req_ex_i = 0;
  check(top->addr_incr_req_o == 1, "address increment was not requested", error_count);
  if (top->addr_incr_req_o) {
    top->adder_result_ex_i = kSecondAddr;
  }
  top->data_gnt_i = 1;
  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  top->eval();
  check(top->data_req_o == 1, "second request was not issued", error_count);
  check(top->data_addr_o == 0x00001004u, "second request address mismatch", error_count);
  check(top->data_be_o == 0x1u, "second request byte enable mismatch", error_count);
  check(top->data_valid_o == 0, "data_valid asserted during second grant", error_count);
  tick(top);

  top->data_gnt_i = 0;
  top->data_rvalid_i = 1;
  top->data_err_i = 1;
  top->eval();
  check(top->data_valid_o == 0, "data_valid asserted before second response", error_count);
  check(top->store_err_o == 0, "store_err asserted before second response", error_count);
  tick(top);

  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  top->eval();
  check(top->data_valid_o == 0, "data_valid asserted while waiting for second response", error_count);
  tick(top);

  top->data_rvalid_i = 1;
  top->data_err_i = 0;
  top->eval();
  check(top->data_valid_o == 1, "data_valid missing on second response", error_count);
  check(top->store_err_o == 1, "store_err missing on second response", error_count);
  check(top->load_err_o == 0, "load_err asserted for store transaction", error_count);
  tick(top);

  top->data_rvalid_i = 0;
  top->eval();
  check(top->busy_o == 0, "lsu remained busy after transaction completion", error_count);

  if (error_count == 0) {
    std::cout << "TB_PASS" << std::endl;
  } else {
    std::cout << "TB_FAIL" << std::endl;
  }

  top->final();
  delete top;
  return 0;
}
EOF

if ! verilator --cc --exe \
  --top-module ibex_load_store_unit \
  --Mdir "${TB_DIR}/obj_dir" \
  -CFLAGS "-std=c++17" \
  /home/ibex/rtl/ibex_load_store_unit.sv \
  "${TB_DIR}/sim_main.cpp"; then
  finish_test "FAIL" 1
fi

if ! make -C "${TB_DIR}/obj_dir" -f Vibex_load_store_unit.mk -j"$(nproc)"; then
  finish_test "FAIL" 1
fi

set +e
"${SIM_BIN}" | tee "${SIM_LOG}"
sim_rc=$?
set -e

if [ "${sim_rc}" -ne 0 ]; then
  finish_test "FAIL" 1
fi

if grep -q '^TB_PASS$' "${SIM_LOG}"; then
  finish_test "PASS" 0
fi

finish_test "FAIL" 1

