#!/bin/bash
cd /home/ibex

set +e
set -u

TEST_NAME="prefetch_request_hold"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include <cstdint>
#include <cstdlib>
#include <iostream>

#include "Vibex_prefetch_buffer.h"
#include "verilated.h"

namespace {

vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

void eval_low(Vibex_prefetch_buffer& top) {
  top.clk_i = 0;
  top.eval();
  ++main_time;
}

void eval_high(Vibex_prefetch_buffer& top) {
  top.clk_i = 1;
  top.eval();
  ++main_time;
}

void tick(Vibex_prefetch_buffer& top) {
  eval_low(top);
  eval_high(top);
}

void expect_state(Vibex_prefetch_buffer& top, const char* tag, bool exp_req, std::uint32_t exp_addr) {
  eval_low(top);
  std::cout << "OBSERVE tag=" << tag
            << " req=" << static_cast<int>(top.instr_req_o)
            << " addr=0x" << std::hex << static_cast<std::uint32_t>(top.instr_addr_o)
            << " busy=" << std::dec << static_cast<int>(top.busy_o) << std::endl;

  if (static_cast<bool>(top.instr_req_o) != exp_req) {
    std::cerr << "ERROR tag=" << tag
              << " expected req=" << exp_req
              << " got req=" << static_cast<int>(top.instr_req_o) << std::endl;
    std::exit(1);
  }

  if (static_cast<std::uint32_t>(top.instr_addr_o) != exp_addr) {
    std::cerr << "ERROR tag=" << tag
              << " expected addr=0x" << std::hex << exp_addr
              << " got addr=0x" << static_cast<std::uint32_t>(top.instr_addr_o)
              << std::dec << std::endl;
    std::exit(1);
  }
}

}  // namespace

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Vibex_prefetch_buffer top;

  top.rst_ni = 0;
  top.req_i = 0;
  top.branch_i = 0;
  top.addr_i = 0;
  top.ready_i = 0;
  top.instr_gnt_i = 0;
  top.instr_rdata_i = 0;
  top.instr_err_i = 0;
  top.instr_pmp_err_i = 0;
  top.instr_rvalid_i = 0;

  tick(top);
  tick(top);
  top.rst_ni = 1;

  top.req_i = 1;
  top.branch_i = 1;
  top.addr_i = 0x00000100;
  top.instr_gnt_i = 1;
  expect_state(top, "branch_grant", true, 0x00000100);
  eval_high(top);

  top.req_i = 0;
  top.branch_i = 0;
  top.instr_gnt_i = 0;
  top.instr_rvalid_i = 1;
  top.instr_rdata_i = 0x00000013;
  tick(top);

  top.instr_rvalid_i = 0;
  top.req_i = 1;
  expect_state(top, "request_without_grant", true, 0x00000104);
  eval_high(top);

  top.req_i = 0;
  expect_state(top, "held_request", true, 0x00000104);

  top.instr_gnt_i = 1;
  expect_state(top, "grant_held_request", true, 0x00000104);
  eval_high(top);

  top.instr_gnt_i = 0;
  top.instr_rvalid_i = 1;
  top.instr_rdata_i = 0x00000013;
  tick(top);

  top.instr_rvalid_i = 0;
  eval_low(top);

  std::cout << "RUNTIME_CHECK: request stayed asserted until grant and address stayed stable" << std::endl;
  top.final();
  return 0;
}
EOF

timeout 1200s verilator --cc --exe --build --sv \
  --top-module ibex_prefetch_buffer \
  --Mdir "${TB_DIR}/obj_dir" \
  "${TB_DIR}/sim_main.cpp" \
  rtl/ibex_fetch_fifo.sv \
  rtl/ibex_prefetch_buffer.sv
build_rc=$?

echo "HWE_BENCH_RESULTS_START"

if [ "${build_rc}" -ne 0 ]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "${build_rc}"
fi

timeout 1200s "${TB_DIR}/obj_dir/Vibex_prefetch_buffer"
run_rc=$?

if [ "${run_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi

echo "HWE_BENCH_RESULTS_END"

exit "${run_rc}"

body:
This PR makes sure the signal `instr_multicycle_done_q` is only evaluated when the decoder currently has a multicycle instruction (load/store, mult/div, branch, jump). If this signal is evaluated
for single-cycle instructions, it can prevent the reg file write enable from being de-asserted in the case of stalls due to the IF stage.

@udinator: Could you please verify that this actually fixes the bug you reported in #216 before we merge it?

