#!/bin/bash
cd /home/ibex || exit 1
set -uo pipefail
set +e

TEST_NAME="if_stall_regfile_we"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_DIR="${TB_DIR}/build"
TB_TOP="${TB_DIR}/ibex_if_stall_tb.sv"
SIM_MAIN="${TB_DIR}/sim_main.cpp"
SIM_LOG="${TB_DIR}/sim.log"
SIM_BIN="${BUILD_DIR}/Vibex_if_stall_tb"

emit_test_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_TOP}" <<'EOF'
module ibex_if_stall_tb (
  input logic clk_i
);
  logic rst_ni = 1'b0;

  logic        instr_req;
  logic        instr_gnt;
  logic        instr_rvalid = 1'b0;
  logic [31:0] instr_addr;
  logic [31:0] instr_rdata = 32'h00000013;

  logic        data_req;
  logic        data_gnt;
  logic        data_rvalid;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_addr;
  logic [31:0] data_wdata;
  logic [31:0] data_rdata;

  logic [31:0] rsp_addr_q = '0;
  logic [31:0] tb_cycles_q = '0;
  logic [31:0] cycle_count_q = '0;
  logic [31:0] stall_cycles_q = '0;
  logic [31:0] bad_stall_cycles_q = '0;
  logic        grant_seen_q = 1'b0;
  logic        rsp_pending_q = 1'b0;
  logic        check_armed_q = 1'b0;

  function automatic logic [31:0] get_instr(input logic [31:0] addr);
    unique case (addr)
      32'h00000080: get_instr = 32'h00100693; // addi x13, x0, 1
      default:      get_instr = 32'h00000013; // nop
    endcase
  endfunction

  assign data_gnt    = 1'b1;
  assign data_rvalid = 1'b1;
  assign data_rdata  = 32'h00000000;

  always_comb begin
    instr_gnt = 1'b0;
    if (rst_ni && instr_req && !grant_seen_q) begin
      instr_gnt = 1'b1;
    end
  end

  always_ff @(posedge clk_i) begin
    tb_cycles_q <= tb_cycles_q + 32'd1;
    rst_ni <= (tb_cycles_q >= 32'd5);

    if (tb_cycles_q < 32'd5) begin
      instr_rvalid        <= 1'b0;
      instr_rdata         <= 32'h00000013;
      rsp_addr_q          <= '0;
      cycle_count_q       <= '0;
      stall_cycles_q      <= '0;
      bad_stall_cycles_q  <= '0;
      grant_seen_q        <= 1'b0;
      rsp_pending_q       <= 1'b0;
      check_armed_q       <= 1'b0;
    end else begin
      cycle_count_q <= cycle_count_q + 32'd1;

      instr_rvalid <= rsp_pending_q;
      if (rsp_pending_q) begin
        instr_rdata <= get_instr(rsp_addr_q);
      end
      rsp_pending_q <= 1'b0;

      if (instr_req && instr_gnt) begin
        grant_seen_q  <= 1'b1;
        rsp_pending_q <= 1'b1;
        rsp_addr_q    <= instr_addr;
        if (instr_addr != 32'h00000080) begin
          $fatal(1, "Unexpected first fetch address: %08x", instr_addr);
        end
      end

      if (grant_seen_q && (ibex_i.id_stage_i.registers_i.rf_reg[13] == 32'h00000001)) begin
        check_armed_q <= 1'b1;
      end

      if (check_armed_q && instr_req && !instr_gnt && !instr_rvalid &&
          !ibex_i.id_stage_i.instr_new_i) begin
        stall_cycles_q <= stall_cycles_q + 32'd1;

        if (ibex_i.id_stage_i.regfile_we) begin
          bad_stall_cycles_q <= bad_stall_cycles_q + 32'd1;
        end

        if (stall_cycles_q == 32'd3) begin
          if (bad_stall_cycles_q != 32'd0 || ibex_i.id_stage_i.regfile_we) begin
            $display("Observed regfile_we=%0b during IF stall; x13=%08x",
                     ibex_i.id_stage_i.regfile_we,
                     ibex_i.id_stage_i.registers_i.rf_reg[13]);
            $fatal(1, "regfile_we stayed asserted during IF stall");
          end

          $display("Observed regfile_we deasserted for four IF stall cycles; x13=%08x",
                   ibex_i.id_stage_i.registers_i.rf_reg[13]);
          $finish;
        end
      end

      if (cycle_count_q > 32'd80) begin
        $fatal(1, "Timed out waiting for IF stall check");
      end
    end
  end

  ibex_core ibex_i (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .test_en_i(1'b0),
    .core_id_i(4'b0),
    .cluster_id_i(6'b0),
    .boot_addr_i(32'h00000000),
    .instr_req_o(instr_req),
    .instr_gnt_i(instr_gnt),
    .instr_rvalid_i(instr_rvalid),
    .instr_addr_o(instr_addr),
    .instr_rdata_i(instr_rdata),
    .data_req_o(data_req),
    .data_gnt_i(data_gnt),
    .data_rvalid_i(data_rvalid),
    .data_we_o(data_we),
    .data_be_o(data_be),
    .data_addr_o(data_addr),
    .data_wdata_o(data_wdata),
    .data_rdata_i(data_rdata),
    .data_err_i(1'b0),
    .irq_software_i(1'b0),
    .irq_timer_i(1'b0),
    .irq_external_i(1'b0),
    .irq_fast_i(15'b0),
    .irq_nm_i(1'b0),
    .debug_req_i(1'b0),
    .fetch_enable_i(1'b1)
  );

endmodule
EOF

cat > "${SIM_MAIN}" <<'EOF'
#include "Vibex_if_stall_tb.h"
#include "verilated.h"

static vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  Vibex_if_stall_tb top;

  while (!Verilated::gotFinish()) {
    top.clk_i = 0;
    top.eval();
    ++main_time;

    top.clk_i = 1;
    top.eval();
    ++main_time;
  }

  top.final();
  return 0;
}
EOF

verilator --cc --build --sv -Wall -Wno-fatal \
  -F rtl/ibex_core.f \
  examples/sim/rtl/prim_clock_gating.sv \
  "${TB_TOP}" \
  --top-module ibex_if_stall_tb \
  --Mdir "${BUILD_DIR}" \
  --exe "${SIM_MAIN}" > "${TB_DIR}/build.log" 2>&1
build_rc=$?

if [ "${build_rc}" -ne 0 ]; then
  cat "${TB_DIR}/build.log"
  emit_test_result "FAIL"
  exit "${build_rc}"
fi

"${SIM_BIN}" 2>&1 | tee "${SIM_LOG}"
sim_rc=${PIPESTATUS[0]}

if [ "${sim_rc}" -eq 0 ]; then
  emit_test_result "PASS"
else
  emit_test_result "FAIL"
fi

exit "${sim_rc}"

