module tb_irq_flush (
  input logic clk_i,
  input logic rst_ni_i
);

  logic        instr_req;
  logic        instr_gnt;
  logic        instr_rvalid;
  logic [31:0] instr_addr;
  logic [31:0] instr_rdata;
  logic        instr_err;

  logic        data_req;
  logic        data_gnt;
  logic        data_rvalid;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_addr;
  logic [31:0] data_wdata;
  logic [31:0] data_rdata;
  logic        data_err;

  logic [31:0] mem [0:255];
  logic [31:0] instr_rdata_q;
  logic [31:0] data_rdata_q;

  integer i;

  localparam logic [31:0] JAL_SELF = 32'h0000006f;

  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      mem[i] = JAL_SELF;
    end

    mem[32'h1c >> 2] = 32'h0a40006f;

    mem[32'h80 >> 2] = 32'h20000093;
    mem[32'h84 >> 2] = 32'h08000113;
    mem[32'h88 >> 2] = 32'h30411073;
    mem[32'h8c >> 2] = 32'h00800193;
    mem[32'h90 >> 2] = 32'h3001a073;
    mem[32'h94 >> 2] = 32'h3001b073;
    mem[32'h98 >> 2] = 32'h00100213;
    mem[32'h9c >> 2] = 32'h0040a023;
    mem[32'ha0 >> 2] = 32'h0000006f;

    mem[32'hc0 >> 2] = 32'h00200213;
    mem[32'hc4 >> 2] = 32'h0040a023;
    mem[32'hc8 >> 2] = 32'h0000006f;
  end

  assign instr_gnt = 1'b1;
  assign instr_err = 1'b0;
  assign data_gnt = 1'b1;
  assign data_err = 1'b0;

  always_ff @(posedge clk_i or negedge rst_ni_i) begin
    if (!rst_ni_i) begin
      instr_rvalid <= 1'b0;
      instr_rdata_q <= 32'h00000013;
    end else begin
      instr_rvalid <= instr_req;
      if (instr_req) begin
        instr_rdata_q <= mem[instr_addr[31:2]];
      end
    end
  end

  assign instr_rdata = instr_rdata_q;

  always_ff @(posedge clk_i or negedge rst_ni_i) begin
    if (!rst_ni_i) begin
      data_rvalid <= 1'b0;
      data_rdata_q <= 32'h0;
    end else begin
      data_rvalid <= data_req;

      if (data_req) begin
        if (data_we) begin
          if (data_be[0]) mem[data_addr[31:2]][7:0] <= data_wdata[7:0];
          if (data_be[1]) mem[data_addr[31:2]][15:8] <= data_wdata[15:8];
          if (data_be[2]) mem[data_addr[31:2]][23:16] <= data_wdata[23:16];
          if (data_be[3]) mem[data_addr[31:2]][31:24] <= data_wdata[31:24];

          if (data_addr == 32'h00000200 && data_be == 4'hf) begin
            if (data_wdata == 32'h00000002) begin
              $display("IRQ_HANDLER_STORE");
              $finish;
            end else if (data_wdata == 32'h00000001) begin
              $display("FAIL_STORE");
              $finish;
            end else begin
              $display("UNEXPECTED_STORE 0x%08x", data_wdata);
              $finish;
            end
          end
        end else begin
          data_rdata_q <= mem[data_addr[31:2]];
        end
      end
    end
  end

  assign data_rdata = data_rdata_q;

  ibex_core dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni_i),
    .test_en_i(1'b0),
    .core_id_i(4'b0),
    .cluster_id_i(6'b0),
    .boot_addr_i(32'h00000000),
    .instr_req_o(instr_req),
    .instr_gnt_i(instr_gnt),
    .instr_rvalid_i(instr_rvalid),
    .instr_addr_o(instr_addr),
    .instr_rdata_i(instr_rdata),
    .instr_err_i(instr_err),
    .data_req_o(data_req),
    .data_gnt_i(data_gnt),
    .data_rvalid_i(data_rvalid),
    .data_we_o(data_we),
    .data_be_o(data_be),
    .data_addr_o(data_addr),
    .data_wdata_o(data_wdata),
    .data_rdata_i(data_rdata),
    .data_err_i(data_err),
    .irq_software_i(1'b0),
    .irq_timer_i(1'b1),
    .irq_external_i(1'b0),
    .irq_fast_i(15'b0),
    .irq_nm_i(1'b0),
    .debug_req_i(1'b0),
    .fetch_enable_i(1'b1)
  );
endmodule
EOF

