#!/bin/bash
cd /home/ibex
set -euo pipefail

TEST_NAME="debug_halt_resume_pc"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
LOG_FILE="${TB_DIR}/sim.log"

finish_test() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/ibex_debug_halt_tb.sv" <<'EOF'
module ibex_debug_halt_tb (
  input  logic clk_i,
  input  logic rst_ni,
  output logic done_o,
  output logic pass_o
);
  localparam logic [31:0] BOOT_ADDR = 32'h00000080;
  localparam logic [31:0] TEST_PC   = 32'h00000084;
  localparam logic [31:0] NEXT_PC   = 32'h00000088;
  localparam logic [31:0] LOOP_PC   = 32'h0000008c;
  localparam logic [31:0] HALT_ADDR = 32'h1a110800;

  logic        instr_req;
  logic        instr_gnt;
  logic        instr_rvalid;
  logic [31:0] instr_addr;
  logic [31:0] instr_rdata;

  logic        data_req;
  logic        data_gnt;
  logic        data_rvalid;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_addr;
  logic [31:0] data_wdata;
  logic [31:0] data_rdata;
  logic        data_err;

  logic        irq_ack;
  logic [4:0]  irq_id;
  logic        debug_req;
  logic        debug_arm_q;
  logic        debug_done_q;

  logic        rvfi_valid;
  logic [63:0] rvfi_order;
  logic [31:0] rvfi_insn;
  logic [31:0] rvfi_insn_uncompressed;
  logic        rvfi_trap;
  logic        rvfi_halt;
  logic        rvfi_intr;
  logic [1:0]  rvfi_mode;
  logic [4:0]  rvfi_rs1_addr;
  logic [4:0]  rvfi_rs2_addr;
  logic [31:0] rvfi_rs1_rdata;
  logic [31:0] rvfi_rs2_rdata;
  logic [4:0]  rvfi_rd_addr;
  logic [31:0] rvfi_rd_wdata;
  logic [31:0] rvfi_pc_rdata;
  logic [31:0] rvfi_pc_wdata;
  logic [31:0] rvfi_mem_addr;
  logic [3:0]  rvfi_mem_rmask;
  logic [3:0]  rvfi_mem_wmask;
  logic [31:0] rvfi_mem_rdata;
  logic [31:0] rvfi_mem_wdata;

  logic        instr_pending_q;
  logic [31:0] instr_addr_q;
  logic        data_pending_q;
  logic        seen_dret_q;
  int unsigned cycle_count_q;

  function automatic logic [31:0] imem_word(input logic [31:0] addr);
    unique case (addr)
      BOOT_ADDR: imem_word = 32'h00000293; // addi x5, x0, 0
      TEST_PC:   imem_word = 32'h00128293; // addi x5, x5, 1
      NEXT_PC:   imem_word = 32'h00100313; // addi x6, x0, 1
      LOOP_PC:   imem_word = 32'h0000006f; // jal x0, 0
      HALT_ADDR: imem_word = 32'h7b200073; // dret
      default:   imem_word = 32'h00000013; // nop
    endcase
  endfunction

  ibex_core_tracer #(
    .MHPMCounterNum(0),
    .MHPMCounterWidth(40),
    .RV32M(1'b1)
  ) dut (
    .clk_i                  (clk_i),
    .rst_ni                 (rst_ni),
    .test_en_i              (1'b0),
    .core_id_i              (4'b0),
    .cluster_id_i           (6'b0),
    .boot_addr_i            (BOOT_ADDR),
    .instr_req_o            (instr_req),
    .instr_gnt_i            (instr_gnt),
    .instr_rvalid_i         (instr_rvalid),
    .instr_addr_o           (instr_addr),
    .instr_rdata_i          (instr_rdata),
    .data_req_o             (data_req),
    .data_gnt_i             (data_gnt),
    .data_rvalid_i          (data_rvalid),
    .data_we_o              (data_we),
    .data_be_o              (data_be),
    .data_addr_o            (data_addr),
    .data_wdata_o           (data_wdata),
    .data_rdata_i           (data_rdata),
    .data_err_i             (data_err),
    .irq_i                  (1'b0),
    .irq_id_i               (5'b0),
    .irq_ack_o              (irq_ack),
    .irq_id_o               (irq_id),
    .debug_req_i            (debug_req),
    .rvfi_valid             (rvfi_valid),
    .rvfi_order             (rvfi_order),
    .rvfi_insn              (rvfi_insn),
    .rvfi_insn_uncompressed (rvfi_insn_uncompressed),
    .rvfi_trap              (rvfi_trap),
    .rvfi_halt              (rvfi_halt),
    .rvfi_intr              (rvfi_intr),
    .rvfi_mode              (rvfi_mode),
    .rvfi_rs1_addr          (rvfi_rs1_addr),
    .rvfi_rs2_addr          (rvfi_rs2_addr),
    .rvfi_rs1_rdata         (rvfi_rs1_rdata),
    .rvfi_rs2_rdata         (rvfi_rs2_rdata),
    .rvfi_rd_addr           (rvfi_rd_addr),
    .rvfi_rd_wdata          (rvfi_rd_wdata),
    .rvfi_pc_rdata          (rvfi_pc_rdata),
    .rvfi_pc_wdata          (rvfi_pc_wdata),
    .rvfi_mem_addr          (rvfi_mem_addr),
    .rvfi_mem_rmask         (rvfi_mem_rmask),
    .rvfi_mem_wmask         (rvfi_mem_wmask),
    .rvfi_mem_rdata         (rvfi_mem_rdata),
    .rvfi_mem_wdata         (rvfi_mem_wdata),
    .fetch_enable_i         (1'b1)
  );

  assign instr_gnt = 1'b1;
  assign data_gnt  = 1'b1;
  assign data_err  = 1'b0;

  // Keep debug_req asserted until the core actually transitions into debug mode.
  assign debug_req = rst_ni && debug_arm_q &&
                     !dut.u_ibex_core.id_stage_i.controller_i.debug_mode_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      instr_pending_q <= 1'b0;
      instr_addr_q    <= '0;
      instr_rvalid    <= 1'b0;
      instr_rdata     <= 32'h00000013;
      data_pending_q  <= 1'b0;
      data_rvalid     <= 1'b0;
      data_rdata      <= '0;
    end else begin
      instr_rvalid    <= instr_pending_q;
      instr_rdata     <= imem_word(instr_addr_q);
      instr_pending_q <= instr_req;
      instr_addr_q    <= instr_addr;

      data_rvalid     <= data_pending_q;
      data_rdata      <= 32'h00000000;
      data_pending_q  <= data_req;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cycle_count_q <= 0;
      debug_arm_q   <= 1'b0;
      debug_done_q  <= 1'b0;
      seen_dret_q   <= 1'b0;
      done_o        <= 1'b0;
      pass_o        <= 1'b0;
    end else begin
      cycle_count_q <= cycle_count_q + 1;

      if (!debug_done_q && !debug_arm_q &&
          dut.u_ibex_core.instr_valid_id &&
          (dut.u_ibex_core.pc_id == TEST_PC)) begin
        debug_arm_q <= 1'b1;
        $display("EVENT: debug_req armed while pc_id=0x%08x", dut.u_ibex_core.pc_id);
      end

      if (debug_arm_q && dut.u_ibex_core.id_stage_i.controller_i.debug_mode_q) begin
        debug_arm_q  <= 1'b0;
        debug_done_q <= 1'b1;
        $display("EVENT: entered debug mode");
      end

      if (rvfi_valid) begin
        $display("TRACE: order=%0d pc=0x%08x insn=0x%08x", rvfi_order, rvfi_pc_rdata,
                 rvfi_insn_uncompressed);

        if (rvfi_insn_uncompressed == 32'h7b200073) begin
          seen_dret_q <= 1'b1;
        end else if (seen_dret_q && !done_o) begin
          $display("RESULT: resumed_pc=0x%08x", rvfi_pc_rdata);
          pass_o <= (rvfi_pc_rdata == NEXT_PC);
          done_o <= 1'b1;
        end
      end

      if (cycle_count_q > 120 && !done_o) begin
        $display("RESULT: timeout");
        pass_o <= 1'b0;
        done_o <= 1'b1;
      end
    end
  end
endmodule
EOF

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include "Vibex_debug_halt_tb.h"
#include "verilated.h"

double sc_time_stamp() { return 0; }

static void tick(Vibex_debug_halt_tb* top) {
  top->clk_i = 0;
  top->eval();
  top->clk_i = 1;
  top->eval();
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  auto* top = new Vibex_debug_halt_tb;
  top->clk_i = 0;
  top->rst_ni = 0;
  top->eval();

  for (int cycle = 0; cycle < 200 && !Verilated::gotFinish(); ++cycle) {
    if (cycle == 5) {
      top->rst_ni = 1;
    }

    tick(top);

    if (top->done_o) {
      int rc = top->pass_o ? 0 : 1;
      top->final();
      delete top;
      return rc;
    }
  }

  top->final();
  delete top;
  return 1;
}
EOF

