tb_script:
#!/bin/bash
cd /home/ibex
set -euo pipefail

TEST_NAME="misaligned_store_split"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
LOG_FILE="${TB_DIR}/sim.log"
BUILD_LOG="${TB_DIR}/build.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb (
    input  logic        clk_i,
    output logic        done_o,
    output logic [31:0] exit_code_o
);

  logic        rst_ni;
  logic        test_en_i;
  logic [ 3:0] core_id_i;
  logic [ 5:0] cluster_id_i;
  logic [31:0] boot_addr_i;
  logic        fetch_enable_i;

  logic        instr_req_o;
  logic        instr_gnt_i;
  logic        instr_rvalid_i;
  logic [31:0] instr_addr_o;
  logic [31:0] instr_rdata_i;

  logic        data_req_o;
  logic        data_gnt_i;
  logic        data_rvalid_i;
  logic        data_we_o;
  logic [ 3:0] data_be_o;
  logic [31:0] data_addr_o;
  logic [31:0] data_wdata_o;
  logic [31:0] data_rdata_i;
  logic        data_err_i;

  logic        irq_i;
  logic [ 4:0] irq_id_i;
  logic        irq_ack_o;
  logic [ 4:0] irq_id_o;
  logic        debug_req_i;

  logic        instr_rsp_pending;
  logic [31:0] instr_rsp_addr_q;
  logic        data_rsp_pending;

  integer reset_cycles;
  integer cycle_count;
  integer store_grants;

  function automatic logic [31:0] instr_rom(input logic [31:0] addr);
    unique case (addr)
      32'h00000080: instr_rom = 32'h00100093; // addi x1, x0, 1
      32'h00000084: instr_rom = 32'h00000013; // nop
      32'h00000088: instr_rom = 32'h0000A023; // sw x0, 0(x1)
      32'h0000008C: instr_rom = 32'h0000006F; // jal x0, 0
      default:      instr_rom = 32'h00000013;
    endcase
  endfunction

  assign instr_gnt_i = instr_req_o && !instr_rsp_pending;
  assign data_gnt_i  = data_req_o && !data_rsp_pending;

  ibex_core dut (
      .clk_i          ( clk_i          ),
      .rst_ni         ( rst_ni         ),
      .test_en_i      ( test_en_i      ),
      .core_id_i      ( core_id_i      ),
      .cluster_id_i   ( cluster_id_i   ),
      .boot_addr_i    ( boot_addr_i    ),
      .instr_req_o    ( instr_req_o    ),
      .instr_gnt_i    ( instr_gnt_i    ),
      .instr_rvalid_i ( instr_rvalid_i ),
      .instr_addr_o   ( instr_addr_o   ),
      .instr_rdata_i  ( instr_rdata_i  ),
      .data_req_o     ( data_req_o     ),
      .data_gnt_i     ( data_gnt_i     ),
      .data_rvalid_i  ( data_rvalid_i  ),
      .data_we_o      ( data_we_o      ),
      .data_be_o      ( data_be_o      ),
      .data_addr_o    ( data_addr_o    ),
      .data_wdata_o   ( data_wdata_o   ),
      .data_rdata_i   ( data_rdata_i   ),
      .data_err_i     ( data_err_i     ),
      .irq_i          ( irq_i          ),
      .irq_id_i       ( irq_id_i       ),
      .irq_ack_o      ( irq_ack_o      ),
      .irq_id_o       ( irq_id_o       ),
      .debug_req_i    ( debug_req_i    ),
      .fetch_enable_i ( fetch_enable_i )
  );

  initial begin
    rst_ni            = 1'b0;
    test_en_i         = 1'b0;
    core_id_i         = 4'h0;
    cluster_id_i      = 6'h0;
    boot_addr_i       = 32'h0000_0000;
    fetch_enable_i    = 1'b1;
    irq_i             = 1'b0;
    irq_id_i          = 5'h0;
    debug_req_i       = 1'b0;
    instr_rvalid_i    = 1'b0;
    instr_rdata_i     = 32'h0000_0013;
    data_rvalid_i     = 1'b0;
    data_rdata_i      = 32'h0000_0000;
    data_err_i        = 1'b0;
    instr_rsp_pending = 1'b0;
    instr_rsp_addr_q  = 32'h0;
    data_rsp_pending  = 1'b0;
    reset_cycles      = 0;
    cycle_count       = 0;
    store_grants      = 0;
    done_o            = 1'b0;
    exit_code_o       = 32'd1;
  end

  always_ff @(posedge clk_i) begin
    if (!done_o) begin
      if (reset_cycles < 5) begin
        reset_cycles <= reset_cycles + 1;
        rst_ni       <= 1'b0;
      end else begin
        rst_ni       <= 1'b1;
      end
    end
  end

  always_ff @(posedge clk_i) begin
    instr_rvalid_i <= 1'b0;
    if (!rst_ni) begin
      instr_rsp_pending <= 1'b0;
      instr_rsp_addr_q  <= 32'h0;
      instr_rdata_i     <= 32'h0000_0013;
    end else begin
      if (instr_rsp_pending) begin
        instr_rvalid_i    <= 1'b1;
        instr_rdata_i     <= instr_rom(instr_rsp_addr_q);
        instr_rsp_pending <= 1'b0;
        $display("IFETCH addr=%08x data=%08x", instr_rsp_addr_q, instr_rom(instr_rsp_addr_q));
      end

      if (instr_req_o && instr_gnt_i) begin
        instr_rsp_pending <= 1'b1;
        instr_rsp_addr_q  <= instr_addr_o;
      end
    end
  end

  always_ff @(posedge clk_i) begin
    data_rvalid_i <= 1'b0;
    data_err_i    <= 1'b0;
    if (!rst_ni) begin
      data_rsp_pending <= 1'b0;
    end else begin
      if (data_rsp_pending) begin
        data_rvalid_i    <= 1'b1;
        data_rdata_i     <= 32'h0000_0000;
        data_rsp_pending <= 1'b0;
      end

      if (data_req_o && data_gnt_i) begin
        data_rsp_pending <= 1'b1;

        if (data_we_o) begin
          $display("STORE_GRANT %0d addr=%08x be=%04b wdata=%08x",
                   store_grants + 1, data_addr_o, data_be_o, data_wdata_o);

          if (store_grants == 0) begin
            if ((data_addr_o != 32'h0000_0000) || (data_be_o != 4'b1110)) begin
              $display("FAIL first beat mismatch");
              done_o      <= 1'b1;
              exit_code_o <= 32'd1;
            end
          end else if (store_grants == 1) begin
            if ((data_addr_o != 32'h0000_0004) || (data_be_o != 4'b0001)) begin
              $display("FAIL second beat mismatch");
              done_o      <= 1'b1;
              exit_code_o <= 32'd1;
            end else begin
              $display("PASS observed correct misaligned store split");
              done_o      <= 1'b1;
              exit_code_o <= 32'd0;
            end
          end else begin
            $display("FAIL unexpected extra store beat");
            done_o      <= 1'b1;
            exit_code_o <= 32'd1;
          end

          store_grants <= store_grants + 1;
        end
      end
    end
  end

  always_ff @(posedge clk_i) begin
    if (!rst_ni) begin
      cycle_count <= 0;
    end else if (!done_o) begin
      cycle_count <= cycle_count + 1;
      if (cycle_count > 200) begin
        $display("FAIL timeout waiting for split store");
        done_o      <= 1'b1;
        exit_code_o <= 32'd1;
      end
    end
  end

endmodule
EOF

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include <cstdint>
#include <iostream>

#include <verilated.h>
#include "Vtb.h"

double sc_time_stamp() { return 0.0; }

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  Vtb top;
  std::uint64_t cycles = 0;

  top.clk_i = 0;
  top.eval();

  while (!Verilated::gotFinish()) {
    top.clk_i = 0;
    top.eval();
    top.clk_i = 1;
    top.eval();

    if (top.done_o) {
      int rc = static_cast<int>(top.exit_code_o & 0xffU);
      top.final();
      return rc;
    }

    cycles++;
    if (cycles > 1000) {
      std::cerr << "FAIL harness timeout" << std::endl;
      top.final();
      return 1;
    }
  }

  top.final();
  return 1;
}
EOF

report_test() {
  local status="$1"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

if ! timeout 900 verilator -Wall -Wno-fatal -Wno-DECLFILENAME -Wno-UNUSED \
    --cc --exe --build --top-module tb -Mdir "${TB_DIR}/obj_dir" \
    "${TB_DIR}/tb.sv" "${TB_DIR}/sim_main.cpp" \
    dv/uvm/tb/prim_clock_gating.sv \
    rtl/ibex_defines.sv rtl/ibex_tracer_defines.sv rtl/ibex_alu.sv \
    rtl/ibex_compressed_decoder.sv rtl/ibex_controller.sv rtl/ibex_cs_registers.sv \
    rtl/ibex_decoder.sv rtl/ibex_int_controller.sv rtl/ibex_ex_block.sv \
    rtl/ibex_id_stage.sv rtl/ibex_if_stage.sv rtl/ibex_load_store_unit.sv \
    rtl/ibex_multdiv_slow.sv rtl/ibex_multdiv_fast.sv rtl/ibex_prefetch_buffer.sv \
    rtl/ibex_fetch_fifo.sv rtl/ibex_register_file_ff.sv rtl/ibex_core.sv \
    >"${BUILD_LOG}" 2>&1; then
  cat "${BUILD_LOG}"
  report_test "FAIL"
  exit 1
fi

if timeout 60 "${TB_DIR}/obj_dir/Vtb" | tee "${LOG_FILE}"; then
  report_test "PASS"
  exit 0
fi

cat "${LOG_FILE}"
report_test "FAIL"
exit 1
